import{_ as n,o as a,c as t,ak as i,bl as r,bm as o,bq as s,bp as l,br as u,bs as p,bt as m}from"./chunks/framework.Ca1nQs_n.js";const q=JSON.parse('{"title":"Animation par interpolation avec la fenêtre Animation","description":"","frontmatter":{},"headers":[],"relativePath":"16_AnimationParInterpolation.md","filePath":"16_AnimationParInterpolation.md","lastUpdated":1769182706000}'),c={name:"16_AnimationParInterpolation.md"};function d(f,e,g,b,h,v){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="animation-par-interpolation-avec-la-fenetre-animation" tabindex="-1">Animation par interpolation avec la fenêtre Animation <a class="header-anchor" href="#animation-par-interpolation-avec-la-fenetre-animation" aria-label="Permalink to “Animation par interpolation avec la fenêtre Animation”">​</a></h1><p>L&#39;animation par interpolation est une technique qui permet de créer des animations fluides en définissant des points clés (keyframes) pour les propriétés d&#39;un objet, telles que la position, la rotation ou l&#39;échelle. Unity offre un système puissant pour créer ce type d&#39;animation à l&#39;aide de la fenêtre Animation.</p><p>La fenêtre Animation permet de définir des keyframes pour différentes propriétés d&#39;un GameObject, et Unity interpole automatiquement les valeurs entre ces keyframes pour créer une transition fluide.Il est possible d&#39;enregistrer les changements des propriétés d&#39;un GameObject au fil du temps, et Unity génère les frames intermédiaires.</p><h2 id="proprietes-animables" tabindex="-1">Propriétés animables <a class="header-anchor" href="#proprietes-animables" aria-label="Permalink to “Propriétés animables”">​</a></h2><p>Dans Unity, la majorité des propriétés des composants peuvent être animées, y compris :</p><ul><li>Position, rotation et échelle d&#39;un GameObject (Transform)</li><li>Couleur et transparence (Renderer, Light, UI)</li><li>Paramètres des composants (volume de l&#39;AudioSource, intensité de la lumière, etc.)</li><li>Propriétés des éléments UI (couleur de texte, taille, position)</li></ul><h2 id="creation-d-une-animation-par-interpolation" tabindex="-1">Création d&#39;une animation par interpolation <a class="header-anchor" href="#creation-d-une-animation-par-interpolation" aria-label="Permalink to “Création d&#39;une animation par interpolation”">​</a></h2><ol><li>Ouvrez la fenêtre <strong>Animation</strong> en allant dans le menu <strong>Window &gt; Animation &gt; Animation</strong>.</li><li>Sélectionnez le GameObject auquel vous souhaitez ajouter l&#39;animation (par exemple, un personnage ou un objet).</li><li>Dans la fenêtre Animation, cliquez sur le bouton <strong>Create</strong> pour créer une nouvelle animation. Cela va ajouter un composant <strong>Animator</strong> au GameObject si ce n&#39;est pas déjà fait et créer un fichier d&#39;animation dans le dossier <code>Assets/animations</code>.</li><li>Enregistrez le fichier d&#39;animation avec un nom approprié au format suivant <code>objet_nomDeLanimation</code> (par exemple, &quot;porte_ouverture&quot;, &quot;lumiere_clignotante&quot;).</li></ol><p><img src="'+r+'" alt="Créer un composant animator" width="100%"><img src="'+o+'" alt="Enregistrement d&#39;une animation"></p><ol start="5"><li>Dans la fenêtre Animation, assurez-vous que le mode d&#39;enregistrement est activé en cliquant sur le bouton rouge <strong>Record</strong> (si ce n&#39;est pas déjà fait).</li></ol><p><img src="'+s+'" alt="Enregistrement des propriétés animables"></p><ol start="6"><li>Déplacez la tête de lecture (le curseur vertical rouge) à l&#39;endroit où vous souhaitez définir un keyframe (par exemple, à 1 seconde).</li><li>Modifiez la propriété du GameObject que vous souhaitez animer (par exemple, la position, la rotation ou l&#39;échelle). Unity ajoutera automatiquement un keyframe pour cette propriété à la position actuelle de la tête de lecture.</li><li>Répétez les étapes 6 et 7 pour définir d&#39;autres keyframes à différents moments dans le temps.</li><li>Une fois que vous avez défini tous les keyframes nécessaires, désactivez le mode d&#39;enregistrement en cliquant à nouveau sur le bouton <strong>Record</strong>. <strong>N&#39;oubliez pas cette étape, sinon vous continuerez à ajouter des keyframes involontairement.</strong></li></ol><h3 id="deplacement-par-programmation-et-animation-par-interpolation" tabindex="-1">Déplacement par programmation et animation par interpolation <a class="header-anchor" href="#deplacement-par-programmation-et-animation-par-interpolation" aria-label="Permalink to “Déplacement par programmation et animation par interpolation”">​</a></h3><p>Si vous souhaitez déplacer un GameObject par programmation ET en utilisant aussi une animation par interpolation, vous pouvez le faire en combinant les deux approches.</p><p>Cependant, il est important de noter que les animations peuvent écraser les modifications par programmation si elles affectent les mêmes propriétés.</p><p>Pour éviter cela, <strong>placez l&#39;élément animé dans un GameObject parent et appliquez les scripts de déplacement par programmation au parent.</strong></p><p><img src="'+l+'" alt="Combiner script et animation "></p><h2 id="creer-une-animation-qui-joue-en-boucle-correctement" tabindex="-1">Créer une animation qui joue en boucle correctement <a class="header-anchor" href="#creer-une-animation-qui-joue-en-boucle-correctement" aria-label="Permalink to “Créer une animation qui joue en boucle correctement”">​</a></h2><p>Pour qu&#39;une animation joue en boucle, assurez-vous que la dernière image-clé de l&#39;animation correspond à la première frame.</p><ol><li>Dans la fenêtre Animation, sélectionnez les images-clés sur la première frame de l&#39;animation.</li><li>Copiez les valeurs des propriétés de la première frame (par exemple, position, rotation, échelle).</li><li>Déplacez la tête de lecture à la dernière frame de l&#39;animation et collez ces valeurs.</li></ol><h2 id="types-d-interpolation" tabindex="-1">Types d&#39;interpolation <a class="header-anchor" href="#types-d-interpolation" aria-label="Permalink to “Types d&#39;interpolation”">​</a></h2><p>Unity utilise les courbes de Bezier comme dans Illustrator pour interpoler entre les images-clés. Vous pouvez voir ces courbes en appuyant sur le bouton <strong>Curves</strong> dans la fenêtre Animation et en sélectionnant une propriété animée.Il faut parfois déplier une propriété animée pour voir la courbe.</p><p><img src="'+u+'" alt="Courbes d&#39;animation"></p><p>Vous pouvez modifier la manière dont les poignées des courbes réagissent en cliquant avec le bouton droit sur une image-clé dans la fenêtre Animation. Vous pouvez choisir parmi plusieurs types d&#39;interpolation, tels que :</p><ul><li>Clamped Auto : Les poignées sont automatiquement ajustées, mais restent dans les limites des keyframes adjacentes</li><li>Auto : Les poignées sont automatiquement ajustées pour une transition fluide</li><li>Free Smooth : Les poignées sont libres et lisses pour un contrôle manuel</li><li>Flat : Les poignées sont horizontales, créant une transition douce</li><li>Broken : Chaque poignée peut être ajustée indépendamment, ce qui permet des transitions plus complexes</li></ul><p><img src="'+p+'" alt="Types d&#39;interpolation"></p><p>Vous pouvez également choisir comment la courbe se comporte entre à chaque poignée:</p><ul><li>Free : La courbe d&#39;animation est librement ajustable entre les keyframes</li><li>Linear : La courbe d&#39;animation est une ligne droite entre les keyframes. Donne une animation à vitesse constante</li><li>Constant : La valeur reste constante jusqu&#39;à la prochaine keyframe. Il n&#39;y a pas de transition entre les keyframes. Utile pour des changements brusques</li><li>Stepped : La valeur change brusquement à la keyframe suivante. Utilisé pour des animations en &quot;sauts&quot; comme des animations de sprites</li></ul><p><img src="'+m+'" alt="Comportement de chaque poignée d&#39;animation"></p><p>Pour visualiser les différentes courbes d&#39;interpolation, vous pouvez visiter les sites suivants :</p><p><a href="https://www.svgator.com/blog/easing-functions/" target="_blank" rel="noreferrer">SVGator - Easing Functions</a><a href="https://docs.unity3d.com/2019.1/Documentation/Manual/animeditor-AnimationCurves.html" target="_blank" rel="noreferrer">Documentation Unity - Animation Curves </a></p><h2 id="conseils-pour-une-animation-reussie" tabindex="-1">Conseils pour une animation réussie <a class="header-anchor" href="#conseils-pour-une-animation-reussie" aria-label="Permalink to “Conseils pour une animation réussie”">​</a></h2><ul><li><strong>Utilisez des courbes d&#39;animation</strong> : Dans la fenêtre Animation, vous pouvez ajuster les courbes d&#39;animation pour contrôler la vitesse et l&#39;accélération des transitions entre les keyframes.</li><li><strong>Organisez vos animations</strong> : Utilisez des dossiers dans le panneau Project pour organiser vos fichiers d&#39;animation et gardez une structure claire.</li><li><strong>Nommez vos animations de manière descriptive</strong> : Utilisez des noms clairs et descriptifs pour vos animations afin de faciliter leur identification et commençant par le nom de l&#39;objet animé et le type d&#39;animation (ex : &quot;porte_ouverture&quot;, &quot;lumiere_clignotante&quot;).</li><li><strong>Testez régulièrement</strong> : Jouez l&#39;animation dans la fenêtre Animation pour voir comment elle se déroule et apportez des ajustements si nécessaire.</li></ul><p><a href="https://docs.unity3d.com/Manual/animeditor-UsingAnimationEditor.html" target="_blank" rel="noreferrer">Documentation officielle Unity sur la fenêtre d&#39;animation</a></p>',34)])])}const z=n(c,[["render",d]]);export{q as __pageData,z as default};
